//! The object registry: every NID OpenSSL assigns, with its names and OID. The tables are
//! generated by `cargo xtask codegen` from the vendored headers.

use core::cmp::Ordering;
use std::sync::OnceLock;

/// One entry of the object table.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ObjectDef {
    /// OpenSSL's numeric identifier for the object (NID).
    pub nid: i32,
    /// Short name (`SN_`). OpenSSL fills it from the long name when an object has none.
    pub short_name: &'static str,
    /// Long name (`LN_`), likewise filled from the short name.
    pub long_name: &'static str,
    /// Content octets of the DER-encoded OBJECT IDENTIFIER; empty for objects without one,
    /// including the single-arc roots `undef`, `iso`, `itu-t`, and `joint-iso-itu-t`.
    pub der: &'static [u8],
    /// Whether OpenSSL's index of objects by OID holds it: whether `obj_mac.h` defines its
    /// `OBJ_` macro, which is so for every object with `der` and for a few without.
    pub indexed: bool,
}

/// A signature algorithm with the digest and public-key algorithm it combines, as NIDs.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SignatureAlgorithm {
    pub signature: i32,
    pub digest: i32,
    pub pkey: i32,
}

/// Every object, indexed by NID. `None` marks NIDs that aren't assigned.
pub fn objects() -> &'static [Option<ObjectDef>] {
    crate::generated::objects::OBJECTS
}

/// The signature algorithms OpenSSL can map to a digest and a public-key algorithm.
pub fn signature_algorithms() -> &'static [SignatureAlgorithm] {
    crate::generated::objects::SIGNATURE_ALGORITHMS
}

/// The object numbered `nid`, if that NID is assigned.
pub fn object(nid: i32) -> Option<&'static ObjectDef> {
    objects().get(usize::try_from(nid).ok()?)?.as_ref()
}

/// The assigned objects in NID order, stably sorted by `key`: OpenSSL's `obj_dat.pl` builds its
/// lookup indexes with Perl's (stable) sort over ascending NIDs.
fn index<K: Ord>(
    keep: impl Fn(&ObjectDef) -> bool,
    key: impl Fn(&ObjectDef) -> K,
) -> Vec<&'static ObjectDef> {
    let mut index: Vec<&'static ObjectDef> =
        objects().iter().flatten().filter(|o| keep(o)).collect();
    index.sort_by_key(|o| key(o));
    index
}

/// OpenSSL's binary search (`ossl_bsearch`) over `index`: the element it stops at decides
/// between equal keys, so the probe sequence is OpenSSL's exactly.
fn search(index: &[&'static ObjectDef], compare: impl Fn(&ObjectDef) -> Ordering) -> Option<i32> {
    let (mut low, mut high) = (0usize, index.len());
    while low < high {
        // Both below `index.len()`, so neither the difference nor the sum overflows.
        let middle = low.wrapping_add(high.wrapping_sub(low) >> 1);
        let object = index.get(middle)?;
        match compare(object) {
            Ordering::Less => high = middle,
            Ordering::Greater => low = middle.wrapping_add(1),
            Ordering::Equal => return Some(object.nid),
        }
    }
    None
}

/// The NID with short name `name` (compared as `strcmp` does), as `OBJ_sn2nid` finds it among
/// the built-in objects.
pub fn by_short_name(name: &[u8]) -> Option<i32> {
    static INDEX: OnceLock<Vec<&'static ObjectDef>> = OnceLock::new();
    let index = INDEX.get_or_init(|| index(|_| true, |o| o.short_name.as_bytes()));
    search(index, |o| name.cmp(o.short_name.as_bytes()))
}

/// The NID with long name `name`, as `OBJ_ln2nid` finds it among the built-in objects.
pub fn by_long_name(name: &[u8]) -> Option<i32> {
    static INDEX: OnceLock<Vec<&'static ObjectDef>> = OnceLock::new();
    let index = INDEX.get_or_init(|| index(|_| true, |o| o.long_name.as_bytes()));
    search(index, |o| name.cmp(o.long_name.as_bytes()))
}

/// The NID whose OID has content octets `der`, as `OBJ_obj2nid` finds it among the built-in
/// objects (shorter encodings first, then bytewise). Empty content matches nothing.
pub fn by_der(der: &[u8]) -> Option<i32> {
    static INDEX: OnceLock<Vec<&'static ObjectDef>> = OnceLock::new();
    if der.is_empty() {
        return None;
    }
    let index = INDEX.get_or_init(|| index(|o| o.indexed, |o| (o.der.len(), o.der)));
    search(index, |o| (der.len(), der).cmp(&(o.der.len(), o.der)))
}

/// The digest and public-key algorithms of signature algorithm `signature`.
pub fn signature_by_id(signature: i32) -> Option<&'static SignatureAlgorithm> {
    signature_algorithms()
        .iter()
        .find(|row| row.signature == signature)
}

/// The signature algorithm combining `digest` and `pkey`, as `OBJ_find_sigid_by_algs` finds it
/// among the built-in ones. Its index leaves out the algorithms without a digest, and no two of
/// the rest share a pair, so the first match is OpenSSL's.
pub fn signature_by_algorithms(digest: i32, pkey: i32) -> Option<i32> {
    signature_algorithms()
        .iter()
        .find(|row| row.digest != 0 && row.pkey != 0 && row.digest == digest && row.pkey == pkey)
        .map(|row| row.signature)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_is_indexed_by_nid() {
        for (index, object) in objects().iter().enumerate() {
            if let Some(object) = object {
                assert_eq!(usize::try_from(object.nid).unwrap(), index);
            }
        }
    }

    #[test]
    fn well_known_objects() {
        let sha256 = objects()
            .iter()
            .flatten()
            .find(|o| o.short_name == "SHA256");
        let sha256 = sha256.expect("SHA256 is in the table");
        assert_eq!(sha256.long_name, "sha256");
        assert_eq!(
            sha256.der,
            [0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x02, 0x01]
        );
        let undef = objects()[0].expect("NID 0 is undef");
        assert_eq!((undef.short_name, undef.long_name), ("UNDEF", "undefined"));
        assert!(undef.der.is_empty());
    }

    #[test]
    fn duplicates_resolve_as_openssl_does() {
        // OpenSSL 3.5's obj_dat.h: three objects are named "NULL", and ORG and
        // identified-organization share 1.3; its binary searches stop at these.
        assert_eq!(by_short_name(b"NULL"), Some(1323));
        assert_eq!(by_long_name(b"NULL"), Some(1323));
        assert_eq!(by_der(&[0x2b]), Some(379));
        assert_eq!(by_short_name(b"SHA256"), Some(672));
        assert_eq!(by_long_name(b"sha256"), Some(672));
        assert_eq!(by_short_name(b"sha256"), None);
        assert_eq!(by_der(&[]), None);
    }

    #[test]
    fn signature_lookups() {
        let rsa_sha256 = signature_by_id(668).expect("sha256WithRSAEncryption");
        assert_eq!((rsa_sha256.digest, rsa_sha256.pkey), (672, 6));
        assert_eq!(signature_by_algorithms(672, 6), Some(668));
        // ecdsa-with-Recommended has no digest and isn't in the cross reference.
        assert_eq!(signature_by_algorithms(0, 408), None);
        assert!(signature_by_id(791).is_some_and(|row| row.digest == 0));
    }

    #[test]
    fn signature_algorithms_refer_to_known_objects() {
        // Holes in the table are `None`, so an assigned NID is `Some(Some(_))`.
        let known = |nid: i32| {
            usize::try_from(nid)
                .ok()
                .and_then(|i| objects().get(i))
                .is_some_and(Option::is_some)
        };
        assert!(!signature_algorithms().is_empty());
        for row in signature_algorithms() {
            assert!(
                known(row.signature) && known(row.digest) && known(row.pkey),
                "{row:?}"
            );
        }
    }
}
